import numpy as npfrom numpy import interpimport mathfrom time import timefrom matplotlib.patches import Polygonimport matplotlib.patches as patchesfrom matplotlib.lines import Line2Dimport matplotlib.pyplot as pltfrom casadi import MX, SX, Function, vertcat, dot, nlpsol, cos, sin, norm_2from .spline import BSpline, BSplineBasisfrom .spline_extra import definite_integralfrom .vehicle_basis import VehicleBasisfrom .param import ParamValX, ParamValZ, DecisionVarX, DecisionVarZclass Vehicle(VehicleBasis):    def __init__(self):        super().__init__()        def setup_z_update(self):        self.w, self.lbw, self.ubw = [], [], []        self.g, self.lbg, self.ubg = [], [], []        self.J = 0        self.P = []        self.P0 = []        self.w0 = []        self.w_list, self.g_list, self.P_list = [], [], []                # Define ADMM cost        # x_i - z_i        y = self.define_MX_spline(degree=self.state_degree, knot_intervals=self.knot_intervals, n_spl=self.n_dimensions,                                lower_bound=self.y_min, upper_bound=self.y_max,                                name=["y"] * self.n_dimensions,                                category = 'parameter')        z_i = self.define_MX_spline(degree = self.state_degree, knot_intervals = self.knot_intervals, n_spl = self.n_dimensions,                               lower_bound=self.y_min, upper_bound=self.y_max,                               initial_value = [[self.x0[0], self.xf[0]], [self.x0[1], self.xf[1]]],                               name = ['z_i'] * self.n_dimensions)        lambda_i  = self.define_MX_spline(degree = self.state_degree, knot_intervals = self.knot_intervals, n_spl = self.n_dimensions,                               lower_bound = [], upper_bound = [],                               name = ['lambda_i'] * self.n_dimensions,                               category = 'parameter')                """ ---- Frenet ---- """        """ ---- Frenet ---- """        p_sum = 0        q_sum = 0        p_sum += z_i[0]        q_sum += z_i[1]        """ ---- Frenet ---- """        """ ---- Frenet ---- """                    for i in range(len(y)):            self.J += definite_integral(lambda_i[i] * (y[i] - z_i[i]), 0, 1)            self.J += definite_integral(self.rho * (y[i] - z_i[i])**2, 0, 1)        # Cost sum: x_j - z_ij        for i in range(len(self.neighbours)):            y_j = self.define_MX_spline(degree = self.state_degree, knot_intervals = self.knot_intervals, n_spl = self.n_dimensions,                               lower_bound = [], upper_bound = [],                               name = ['y_j'] * self.n_dimensions,                               category = 'parameter')            z_ij = self.define_MX_spline(degree = self.state_degree, knot_intervals = self.knot_intervals, n_spl = self.n_dimensions,                                   lower_bound=self.y_min, upper_bound=self.y_max,                                   initial_value = [[self.neighbours[i].x0[0], self.neighbours[i].xf[0]], [self.neighbours[i].x0[1], self.neighbours[i].xf[1]]],                                   name = ['z_ij'] * self.n_dimensions)            lambda_ij  = self.define_MX_spline(degree = self.state_degree, knot_intervals = self.knot_intervals, n_spl = self.n_dimensions,                                   lower_bound = [], upper_bound = [],                                   name = ['lambda_ij'] * self.n_dimensions,                                   category = 'parameter')            for j in range(len(y)):                self.J += definite_integral(lambda_ij[j] * (y_j[j] - z_ij[j]), 0, 1)                self.J += definite_integral(self.rho * (y_j[j] - z_ij[j])**2, 0, 1)            def cross_product(spline1, spline2):                a1, a2 = spline1[0], spline1[1]                b1, b2 = spline2[0], spline2[1]                return (a1 * b2 - a2 * b1)**2            # vec1: what is should be            # vec2: what we have            # cross: the cross product of the two vectors. It is a function of t.            vec1 = z_i - z_ij            vec2 = np.array(self.xf[:self.n_dimensions]) - np.array(self.neighbours[i].xf[:self.n_dimensions])            cross = cross_product(vec1, vec2)                                    # Formation constraint.            for t in np.linspace(0, 1, self.t_resolution_length):                self.define_constraint([cross(t)],                                        [-self.slack * 1],                                        [self.slack * 1],                                        constraint_type='time',                                        name=["formation_vehicle_" + str(i)] * self.n_dimensions)            # But the dot product should be > 0, to avoid the vehicles switching place and still            # fulfilling the formation requirements (at least for those two vehicles)            # for t in np.linspace(0, 1, self.t_resolution_length):            #     self.define_constraint([dot(t)],            #                             [0],            #                             [math.inf],            #                             constraint_type='time',            #                             name=["formation_dot_vehicle_" + str(i)] * self.n_dimensions)            # TODO: I think this is not really needed anymore, but need to check            # for j in range(len(y)):            #     self.J += self.rho_formation * definite_integral( ((vec1[j] - vec2[j])**2), 0, 1)            """Special distance-constraint"""            """Special distance-constraint"""            frenet_zero = MX((0, 0))            xf = np.array(self.xf[:self.n_dimensions])            xf_j = np.array(self.neighbours[i].xf[:self.n_dimensions])            dist_we_have = (z_i[0] - z_ij[0])**2 \                            + (z_i[1] - z_ij[1])**2            dist_we_want = (xf[0] - xf_j[0])**2 \                            + (xf[1] - xf_j[1])**2            dist_difference = (dist_we_have * 1 - dist_we_want * 0.25) * 1  # 0.5 means we can shrink to the quarter of the size            ""            for t in np.linspace(0, 1, self.t_resolution_length):                self.define_constraint([dist_difference(t)],                                        [0.0],                                        [math.inf],                                        constraint_type='time',                                        name=["formation_vehicle_" + str(i)] * self.n_dimensions)                # We can add collision avoidance here too :)                self.define_constraint([dist_we_have(t)],                                        [(self.radious * 2 * self.vehicle_avoidnce_multiplier)**2],                                        [math.inf],                                        constraint_type='time',                                        name=["formation_vehicle_" + str(i)] * self.n_dimensions)            """Special distance-constraint"""            """Special distance-constraint"""                        """ ---- Frenet ---- """            """ ---- Frenet ---- """            # We add an extra constraint, if we are in the Frenet-frame.                        # Péni féle            # If we add the p components and if we add the q components together,             # each of these should equal to zero. Meaning, the center of gravity             # should be in the (0, 0) point of the Frenet-frame.                        # This is defined outside of this loop :)            # p_sum = z_i[0]            # q_sum = z_i[1]                        p_sum += z_ij[0]            q_sum += z_ij[1]                            """ ---- Frenet ---- """            """ ---- Frenet ---- """                                                    """ ---- Frenet ---- """        """ ---- Frenet ---- """        for t in np.linspace(0, 1, self.t_resolution_length):            self.define_constraint([p_sum(t), q_sum(t)],                                    [-self.slack,-self.slack],                                    [ self.slack, self.slack],                                    constraint_type='time',                                    name=["frenet_zero_" + str(i)] * self.n_dimensions)        """ ---- Frenet ---- """        """ ---- Frenet ---- """        # Containers        self.DvZ = DecisionVarZ(self.w_list, self.g_list, self.lbg, self.ubg)        self.PvZ = ParamValZ(self.P_list, self.P0)        # Initializing values        self.DvZ.extract(self.w0)        "Initialize values with the pre-calculated values from initialize_x()"        if self.initial_values != {}:            self.DvZ.w0_z = self.initial_values["z_i"] + self.initial_values["z_ji"]            self.DvZ.z_i = self.initial_values["z_i"]            self.DvZ.z_ij = self.initial_values["z_ji"]            self.PvZ.y = self.initial_values["y"]            self.PvZ.y_j = self.initial_values["y_j"]            self.PvZ.lambda_i = self.initial_values["lambda_i"]            self.PvZ.lambda_ij = self.initial_values["lambda_ij"]            self.message_in["y_j"] = self.initial_values["y_j"]            self.message_in["z_ji"] = self.initial_values["z_ji"]            self.message_in["lambda_ji"] = self.initial_values["lambda_ji"]                # Creating solver class        prob = {'f': self.J,                'x': vertcat(*self.w),                'g': vertcat(*self.g),                'p': vertcat(*self.P)                }        self.solver_z = nlpsol('solver', 'ipopt', prob, self.options_z)        # Assembling the argument dictionary        self.arg_z = {'x0' : self.w0,                   'lbx': self.lbw,                   'ubx': self.ubw,                   'lbg': self.lbg,                   'ubg': self.ubg,                   'p': self.PvZ.assemble()}        return self        def z_update(self):        self.update_PvZ()        # Updating the necessary arguments for the solver        self.arg_z['x0'] = self.DvZ.w0_z        self.arg_z['p'] = self.PvZ.assemble()        # Solving the problem        # t1 = time.time()        self.solution_z = self.solver_z.call(self.arg_z)        # t2 = time.time()        # self.z_update_time += [t2-t1]        # Extracting the solution        self.DvZ.extract(self.solution_z)        return self        def setup_x_update(self):        self.w, self.lbw, self.ubw = [], [], []        self.g, self.lbg, self.ubg = [], [], []        self.J = 0        self.P = []        self.P0 = []        self.w0 = []        self.w_list, self.g_list, self.P_list = [], [], []        pq = self.define_MX_spline(degree=3, knot_intervals=self.knot_intervals, n_spl=self.n_dimensions,                                lower_bound=self.y_min, upper_bound=self.y_max,                                initial_value = [[self.x0[0], self.xf[0]], [self.x0[1], self.xf[1]]],                                name=["y"] * self.n_dimensions)        y = pq # we basically rename the thing :)        pq_dot = [pq_.derivative() for pq_ in pq]        pq_dotdot = [pq_dot_.derivative() for pq_dot_ in pq]        p = pq[0]        q = pq[1]                p_dot = pq_dot[0]        q_dot = pq_dot[1]                p_dotdot = pq_dotdot[0]        q_dodott = pq_dotdot[1]                # Initial position constraint on y        self.define_constraint([p, q],                                self.x0[:self.n_dimensions],                                self.x0[:self.n_dimensions],                                constraint_type='initial',                                name=["y0"] * self.n_dimensions)        # Initial velocity constraint on dy        self.define_constraint([p_dot, q_dot],                                self.x0[self.n_dimensions:self.n_dimensions*2],                                self.x0[self.n_dimensions:self.n_dimensions*2],                                constraint_type='initial',                                name=["dy0"] * self.n_dimensions)        # Final position constraint on y        self.define_constraint([p, q],                                self.xf[:self.n_dimensions],                                self.xf[:self.n_dimensions],                                constraint_type='final',                                name=["yf"] * self.n_dimensions)        # Final velocity constraint on dy        self.define_constraint([p_dot, q_dot],                                self.xf[self.n_dimensions:self.n_dimensions*2],                                self.xf[self.n_dimensions:self.n_dimensions*2],                                constraint_type='final',                                name=["dyf"] * self.n_dimensions)        # TODO: overall constraints on y, dy and u        # Invoke the frenet frame so that we can fill up the parameters        v_s  = self.fp.fx_d_spline + self.fp.fy_d_spline        sin_theta_c = self.fp.sin_f_theta_spline        cos_theta_c = self.fp.cos_f_theta_spline        curvature = self.fp.fy_c_spline                                # This is what we are going to do... We will be searching for p_dot and q_dot values        # that are not equal to the value that the system dynamics dictates. Instead         # we replace vx & vy with their minimum and maximum values. This gives us constraints        # on how we are allowed to choose p_dot and q_dot. Thus, we will find optimal values for        # the states of the system that adhere to the minimum and maximum constraints of vx & vy.        # This, of course is not enough, later we need to do something similar for p_dotdot, q_dotdot / ax, ay.        # Furthermore, we will plot the constraints just so we can see wether we even can find a solution or not.        # And using these values will we calculate vx, vy and ax, ay after the fact :)                        [equation_min_p, equation_max_p] = self.fp.equation_min_max('p')        [equation_min_q, equation_max_q] = self.fp.equation_min_max('q')                # Okay... well... coefficient reduction wasn't enough, because the problem is        # the multiplication: curvature * p.        # For this reason: we have to time-sample the whole thing right here and now. Meh...                "p_dot equation"        for t in np.linspace(0, 1, self.t_resolution_length):            expression1 = -p_dot(t) -v_s(t) * (1 - curvature(t) * q(t)) + equation_min_p(t)            expression2 = -p_dot(t) -v_s(t) * (1 - curvature(t) * q(t)) + equation_max_p(t)                        self.define_constraint([expression1],                                    [-math.inf],                                    [0],                                    constraint_type='time',                                    name=["p_dot_min"])                        self.define_constraint([expression2],                                    [0],                                    [math.inf],                                    constraint_type='time',                                    name=["p_dot_max"])                                "q_dot equation"        for t in np.linspace(0, 1, self.t_resolution_length):            expression1 = -q_dot(t) -v_s(t) * p(t) * curvature(t) + equation_min_q(t)            expression2 = -q_dot(t) -v_s(t) * p(t) * curvature(t) + equation_max_q(t)                        self.define_constraint([expression1],                                    [-math.inf],                                    [0],                                    constraint_type='time',                                    name=["q_dot_min"])                        self.define_constraint([expression2],                                    [0],                                    [math.inf],                                    constraint_type='time',                                    name=["q_dot_max"])                                # Collision avoidance with obstacles and neighbours or w.t.f.?        for i, obstacle in enumerate(self.obstacles):            self.collision_avoidance_hyperplane([p, q], obstacle.corners_spline,                                                radious=self.radious, name="obst_" + str(i),                                                constraint_type='spline_obstacle_spline_t',                                                n_samples=self.t_resolution_length)                    # Cost function        # TODO In frenet frame this cost function does not apply! It needs to be changed!        cost = 0        for i in range(len(pq_dotdot)):            cost += pq_dotdot[i]**2        # Cost for: acceleration in the frenet frame        self.J += self.rho_input * definite_integral(cost, 0, 1)                # Cost x_i - z_i        z_i = self.define_MX_spline(degree = 3, knot_intervals = self.knot_intervals, n_spl = self.n_dimensions,                               lower_bound = [], upper_bound = [],                               name = ['z_i'] * self.n_dimensions,                               category = 'parameter')        lambda_i  = self.define_MX_spline(degree = 3, knot_intervals = self.knot_intervals, n_spl = self.n_dimensions,                               lower_bound = [], upper_bound = [],                               name = ['lambda_i'] * self.n_dimensions,                               category = 'parameter')        for i in range(len(y)):            self.J += definite_integral(lambda_i[i] * (y[i] - z_i[i]), 0, 1)            self.J += definite_integral(self.rho * (y[i] - z_i[i])**2, 0, 1)        # Cost sum: x_i - z_ji        for i in range(len(self.neighbours)):            z_ji = self.define_MX_spline(degree = 3, knot_intervals = self.knot_intervals, n_spl = self.n_dimensions,                                   lower_bound = [], upper_bound = [],                                   name = ['z_ji'] * self.n_dimensions,                                   category = 'parameter')            lambda_ji  = self.define_MX_spline(degree = 3, knot_intervals = self.knot_intervals, n_spl = self.n_dimensions,                                   lower_bound = [], upper_bound = [],                                   name = ['lambda_ji'] * self.n_dimensions,                                   category = 'parameter')            for j in range(len(y)):                self.J += definite_integral(lambda_ji[j] * (y[j] - z_ji[j]), 0, 1)                self.J += definite_integral(self.rho * (y[j] - z_ji[j])**2, 0, 1)            # # Inter-vehicle collision avoidance            # for i, neighbour in enumerate(self.neighbours):            #     self.collision_avoidance_hyperplane(y, z_ji, radious = self.radious/10, name = "inter_vehicle" + str(i), constraint_type="inter_vehicle")        # Containers        self.DvX = DecisionVarX(self.w_list, self.g_list, self.lbg, self.ubg)        self.PvX = ParamValX(self.P_list, self.P0)        # self.PvX.obst = tempOOO        # Initializing values - below this is overwritten by the initial values        # found during initialize_x()        self.DvX.extract(self.w0)        "Initialize values with the pre-calculated values from initialize_x()"        if self.initial_values != {}:            self.DvX.extract(self.initial_values["w0_initial"])            self.PvX.z_i = self.initial_values["z_i"]            self.PvX.z_ji = self.initial_values["z_ji"]            self.PvX.lambda_i = self.initial_values["lambda_i"]            self.PvX.lambda_ji = self.initial_values["lambda_ji"]            self.message_in["y_j"] = self.initial_values["y_j"]            self.message_in["z_ji"] = self.initial_values["z_ji"]            self.message_in["lambda_ji"] = self.initial_values["lambda_ji"]        # Creating solver class        prob = {'f': self.J,                'x': vertcat(*self.w),                'g': vertcat(*self.g),                'p': vertcat(*self.P)                }        self.solver = nlpsol('solver', 'ipopt', prob, self.options)        # Assembling the argument dictionary        self.arg = {'x0' : self.w0,                   'lbx': self.lbw,                   'ubx': self.ubw,                   'lbg': self.lbg,                   'ubg': self.ubg,                   'p': self.PvX.assemble()}        return self    def x_update(self):        self.update_PvX()        # Updating the necessary arguments for the solver        self.arg['x0'] = self.DvX.w0        self.arg['p'] = self.PvX.assemble()        # Solving the problem        self.solution = self.solver.call(self.arg)        # Extracting the solution        self.DvX.extract(self.solution)        return self            ###########################################################################    ###########################################################################    ###########################################################################    ###########################################################################    ###########################################################################    ###########################################################################    ###########################################################################    "Plotting"        def plot_vehicle_frenet_trajectories(self, ax):        flatten = lambda t: [item for sublist in t for item in sublist]        # Plotting the environment        ax = self.plot_environment(ax)        # Creating the splines        basis = self.define_knots(degree = 3, knot_intervals = self.knot_intervals)        solution = self.solution['x'].full()        coeffs1 = flatten([solution[x] for x in np.arange(0, len(basis))])        coeffs2 = flatten([solution[x] for x in np.arange(len(basis), len(basis)*2)])        p_solution = BSpline(basis, coeffs1)        q_solution = BSpline(basis, coeffs2)                # Sampling        t = np.linspace(0, 1, 100)                x_t, y_t = [], []        for t_ in t:            p_solution_, q_solution_ = p_solution(t_)[0], q_solution(t_)[0]            x_, y_ = self.fp.frenet_to_inertial(p_solution_, q_solution_, t_)            x_t += [x_]            y_t += [y_]                "Below is the same as for the generic plot_vehicle_trajecotries()"                # Fitting a polynome of degree 7 onto the spline        poly7_x = np.poly1d(np.polyfit(t, x_t, deg=7))        poly7_y = np.poly1d(np.polyfit(t, y_t, deg=7))        # Now, the 7 degree polynomials are calculated such that upon evaluation        # between t = [0, 1] we get correct values. Outside this range, they don't        # represent the trajectories we calculated.        # Below we rescale the polynomials such that they give correct values        # between t = [0, t_desired]        # Remember: x^7 --> x^7 / t_desired^7        power = 0        for i in range(len(poly7_x.coeffs)-1, 0-1, -1):            poly7_x.coeffs[i] = poly7_x.coeffs[i] / pow(self.T, power)            poly7_y.coeffs[i] = poly7_y.coeffs[i] / pow(self.T, power)            power += 1        # Let's now sample from this, for the sake of plotting        tp7 = np.linspace(0, self.T, 100)        poly7_x_t = [poly7_x(t_) for t_ in tp7]        poly7_y_t = [poly7_y(t_) for t_ in tp7]        # The path !!! now with correct arrangement of the coefficients !!!        # Storing the coefficients in the format, that crazyswarm requires        # (x^0, x^1, x^2, ...)        poly7_x = poly7_x.coeffs.tolist()        poly7_x.reverse()        poly7_y = poly7_y.coeffs.tolist()        poly7_y.reverse()        # self.write_csv(self.T, poly7_x, poly7_y)        # Adding an extra 7 degree polynomial for hoowering at the end        final_x = poly7_x_t[-1]        final_y = poly7_y_t[-1]        however_x = [final_x] + [0] * 7        however_y = [final_y] + [0] * 7        # Combining the polinomials into a list        T_list = [[self.T], [2]]        poly7_x_list = [poly7_x, however_x]        poly7_y_list = [poly7_y, however_y]        # Writing the list to file        self.write_csv(T_list, poly7_x_list, poly7_y_list)        # ax.plot(poly7_x_t, poly7_y_t, 'k*')        # Plotting of spline & control points        ax.plot(coeffs1, coeffs2, 'ro')        ax.plot(x_t, y_t, 'k')        # Plotting of obstacle        for obstacle in self.obstacles:            obstacle.plot_obstacle(ax)        return ax        ###########################################################################    ###########################################################################    ###########################################################################    ###########################################################################    ###########################################################################    ###########################################################################    ###########################################################################    "Plotting video"        def plot_rotation(self, x, y, theta):        x_new = x * cos(theta) - y * sin(theta)        y_new = x * sin(theta) + y * cos(theta)        return x_new, y_new    def plot_moovie_frames(self, ax, t):        # https://nickcharlton.net/posts/drawing-animating-shapes-matplotlib.html        flatten = lambda t: [item for sublist in t for item in sublist]        # Plotting the environment        ax = self.plot_environment(ax)        # Plotting of obstacle        for obstacle in self.obstacles:            obstacle.plot_obstacle(ax)        # Creating the splines        basis = self.define_knots(degree = 3, knot_intervals = self.knot_intervals)        solution = self.solution['x'].full()        coeffs1 = flatten([solution[x] for x in np.arange(0, len(basis))])        coeffs2 = flatten([solution[x] for x in np.arange(len(basis), len(basis)*2)])        x = BSpline(basis, coeffs1)        y = BSpline(basis, coeffs2)                # # Plotting the trajectory        # x_trajectory = [x(t_)[0] + self.fp.fx_spline(t_)[0][0] for t_ in np.linspace(0, t, 100)]        # y_trajectory = [y(t_)[0] + self.fp.fy_spline(t_)[0][0] for t_ in np.linspace(0, t, 100)]        # ax.plot(x_trajectory, y_trajectory, 'k')                                # Creating the splines        # basis = self.define_knots(degree = 3, knot_intervals = self.knot_intervals)        # solution = self.solution['x'].full()        # coeffs1 = flatten([solution[x] for x in np.arange(0, len(basis))])        # coeffs2 = flatten([solution[x] for x in np.arange(len(basis), len(basis)*2)])        p_solution = BSpline(basis, coeffs1)        q_solution = BSpline(basis, coeffs2)                # Sampling        # t = np.linspace(0, 1, 100)                x_t, y_t = [], []        for t_ in np.linspace(0, t):            p_solution_, q_solution_ = p_solution(t_)[0], q_solution(t_)[0]            x_, y_ = self.fp.frenet_to_inertial(p_solution_, q_solution_, t_)            x_t += [x_]            y_t += [y_]                    ax.plot(x_t, y_t, 'k')                        theta_c = 0        theta_c = self.fp.fy_d_spline(t)[0][0] / self.fp.fx_d_spline(t)[0][0]        # Draw body        radious = 0.05        radious = self.radious * 0.5 * 0.9        height = radious        width = radious        # Draw arms        l = 0.1        l = radious * 2        # x0 = x(t) + self.fp.fx_spline(t)        # y0 = y(t) + self.fp.fy_spline(t)        p_solution_, q_solution_ = p_solution(t)[0], q_solution(t)[0]        x0, y0 = self.fp.frenet_to_inertial(p_solution_, q_solution_, t)        rot_x, rot_y = self.plot_rotation(l, 0, theta_c + np.pi/4)        x1 = x0 + rot_x        y1 = y0 + rot_y        rot_x, rot_y = self.plot_rotation(l, 0, theta_c + np.pi/4*3)        x2 = x0 + rot_x        y2 = y0 + rot_y        rot_x, rot_y = self.plot_rotation(l, 0, theta_c + np.pi/4*5)        x3 = x0 + rot_x        y3 = y0 + rot_y        rot_x, rot_y = self.plot_rotation(l, 0, theta_c + np.pi/4*7)        x4 = x0 + rot_x        y4 = y0 + rot_y        # Rotors        # https://stackoverflow.com/questions/9215658/plot-a-circle-with-pyplot        r_rotor = 0.03        r_rotor = l * 0.3        # Adding stuff to ax        # Lines        line1 = Line2D([x0, x1], [y0, y1], zorder = 8)        line2 = Line2D([x0, x2], [y0, y2], zorder = 8)        line3 = Line2D([x0, x3], [y0, y3], zorder = 8)        line4 = Line2D([x0, x4], [y0, y4], zorder = 8)        ax.add_line(line1)        ax.add_line(line2)        ax.add_line(line3)        ax.add_line(line4)        # Circles        circle1 = plt.Circle((x1, y1), r_rotor, color='k', alpha=0.5, zorder = 10)        circle2 = plt.Circle((x2, y2), r_rotor, color='k', alpha=0.5, zorder = 10)        circle3 = plt.Circle((x3, y3), r_rotor, color='k', alpha=0.5, zorder = 10)        circle4 = plt.Circle((x4, y4), r_rotor, color='k', alpha=0.5, zorder = 10)        ax.add_patch(circle1)        ax.add_patch(circle2)        ax.add_patch(circle3)        ax.add_patch(circle4)        rect_x = - width/2        rect_y = - height/2        rot_x, rot_y = self.plot_rotation(rect_x, rect_y, theta_c)        rectangle = patches.Rectangle((x0 + rot_x, y0 + rot_y), height, width,                                      linewidth=1, edgecolor='k', facecolor='k',                                      zorder = 9, angle = theta_c / np.pi * 180)        ax.add_patch(rectangle)        return ax